# shellcheck shell=bash
# Generated by matrix-rice (Matrix {{NAME}}). Do not edit: run `matrix-rice <color>`.
# Loaded from ~/.bashrc / ~/.zshrc for interactive shells only.

# `rain`: Matrix code rain in the terminal, in the active color. Ctrl+C or q quits.
rain() {
  if ! command -v cmatrix >/dev/null 2>&1; then
    echo "cmatrix is not installed (sudo apt install cmatrix)" >&2
    return 1
  fi
  cmatrix -ab -u 4 -C "{{CMATRIX}}" "$@"
}

if command -v starship >/dev/null 2>&1; then
  if [ -n "${BASH_VERSION:-}" ]; then
    eval "$(starship init bash)"
  elif [ -n "${ZSH_VERSION:-}" ]; then
    eval "$(starship init zsh)"
  fi
fi

# System banner once per Konsole tab/window (not in nested shells).
if [ -n "${KONSOLE_VERSION:-}" ] && [ -z "${MATRIX_RICE_GREETED:-}" ] && command -v fastfetch >/dev/null 2>&1; then
  export MATRIX_RICE_GREETED=1
  fastfetch
fi
